/**
 * Differential test: TypeScript engines must reproduce the original Python engines bit for bit.
 * Fixture generated by tests/parity/gen_python_cases.py from the ORIGINAL repository.
 */
import { describe, expect, it } from "vitest";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { computeMemberRating } from "../../shared/celestia";
import { computeCharges, dynamicKdiThreshold, getTier } from "../../shared/calculations";

const file = join(__dirname, "python-cases.json");
const cases: any[] = existsSync(file) ? JSON.parse(readFileSync(file, "utf-8")) : [];

describe.skipIf(!cases.length)("parity with original Python engines", () => {
  it(`matches ${cases.length} randomized cases`, () => {
    for (const c of cases) {
      const i = c.input;
      const [nalAuto, msc] = computeCharges(i.wst, i.ur, i.param, i.dzis);
      expect([nalAuto, msc]).toEqual([c.finance.nal_auto, c.finance.msc]);
      const [, stawka] = getTier(i.ur, i.param, i.dzis);
      expect(stawka).toBe(c.finance.stawka);
      const wpl = i.wplaty.reduce((a: number, [, k]: any) => a + k, 0);
      const rec = i.reczne.reduce((a: number, [, k]: any) => a + k, 0);
      const kor = i.korekty.reduce((a: number, [, k]: any) => a + k, 0);
      const saldo = i.s_start + wpl + kor - (nalAuto + rec);
      expect(saldo).toBe(c.finance.saldo);
      const s_i = Math.max(0, i.s_start) + wpl;
      const z_i = Math.max(0, s_i - saldo);
      expect(dynamicKdiThreshold([{ z_i_gr: z_i, stawka_biezaca_gr: stawka }])).toEqual(c.finance.prog);

      const res = computeMemberRating(
        0,
        { data_wst: i.wst, data_ur: i.ur, reczny_parametr: i.param, saldo_start_gr: i.s_start, saldo_akt_gr: saldo,
          naliczone_gr: nalAuto + rec, kdi_val: c.finance.kdi },
        i.terminy,
        i.wplaty.map(([date, gr]: any) => ({ date, gr })),
        i.reczne.map(([date, gr]: any) => ({ date, gr })),
        i.korekty.map(([date, gr]: any) => ({ date, gr })),
        i.dzis,
      );
      const py = c.celestia;
      const ctx = JSON.stringify(i);
      expect({ score: res.score, rating: res.rating, filary: res.filary }, ctx).toEqual({ score: py.score, rating: py.rating, filary: py.filary });
      expect(res.audyt_glosowan, ctx).toEqual(py.audyt_glosowan);
      expect(res.audyt_kwartalny.map((a) => ({ ...a, id: a.id ?? null })), ctx).toEqual(py.audyt_kwartalny.map((a: any) => ({ ...a, id: a.id ?? null })));
    }
  });
});
